package de.harryjane.h5179test;
import android.Manifest;import android.app.*;import android.appwidget.AppWidgetManager;import android.bluetooth.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.os.*;import android.provider.Settings;import android.view.View;import android.widget.*;import java.text.DateFormat;import java.util.*;
public class MainActivity extends Activity{
 private static final int REQ=5179;private TextView status,sensor,temp,hum,bat,rssi,updated,diag;
 private final BroadcastReceiver rx=new BroadcastReceiver(){public void onReceive(Context c,Intent i){refresh();String s=i.getStringExtra(H5179ScanService.EXTRA_STATUS);if(s!=null)status.setText(s);}};
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(ui());refresh();status.setText(hasPerm()?"v0.3 bereit. Sensor starten und 20–30 Sekunden warten.":"Bluetooth-Berechtigung wird beim Start angefragt.");}
 @Override protected void onStart(){super.onStart();IntentFilter f=new IntentFilter(H5179ScanService.ACTION_READING);if(Build.VERSION.SDK_INT>=33)registerReceiver(rx,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(rx,f);}
 @Override protected void onStop(){super.onStop();try{unregisterReceiver(rx);}catch(Exception ignored){}}
 private View ui(){ScrollView sc=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(18),dp(18),dp(18));root.setBackgroundColor(Color.rgb(241,246,239));sc.addView(root);TextView title=t("Grow-Tagebuch · H5179 Diagnose v0.3",24,true);title.setTextColor(Color.rgb(32,73,48));root.addView(title);root.addView(t("Alle BLE-Geräte werden sichtbar protokolliert. Damit identifizieren wir deinen H5179 ohne Namensannahme.",14,false));status=t("",15,true);status.setPadding(0,dp(18),0,dp(12));root.addView(status);sensor=row(root,"Sensor");temp=row(root,"Temperatur");hum=row(root,"Luftfeuchte");bat=row(root,"Batterie");rssi=row(root,"Signal");updated=row(root,"Letztes Signal");Button start=btn("BLE-DIAGNOSE STARTEN");start.setOnClickListener(v->start());root.addView(start);Button stop=btn("SCAN STOPPEN");stop.setOnClickListener(v->{stopService(new Intent(this,H5179ScanService.class));status.setText("Scan gestoppt.");});root.addView(stop);TextView dh=t("Gefundene BLE-Geräte",18,true);dh.setPadding(0,dp(20),0,dp(6));root.addView(dh);diag=t("Noch keine Diagnose.",12,false);diag.setTextIsSelectable(true);root.addView(diag);Button widget=btn("KLIMA-WIDGET HINZUFÜGEN");widget.setOnClickListener(v->widget());root.addView(widget);Button bt=btn("BLUETOOTH-EINSTELLUNGEN ÖFFNEN");bt.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_BLUETOOTH_SETTINGS)));root.addView(bt);return sc;}
 private TextView row(LinearLayout root,String l){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setPadding(0,dp(7),0,dp(7));TextView a=t(l,15,true),v=t("—",17,true);a.setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));v.setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));r.addView(a);r.addView(v);root.addView(r);return v;}
 private TextView t(String s,int z,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.rgb(35,45,38));if(bold)v.setTypeface(v.getTypeface(),1);return v;}private Button btn(String s){Button b=new Button(this);b.setText(s);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);b.setLayoutParams(p);return b;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 private void start(){if(!hasPerm()){request();return;}BluetoothManager bm=(BluetoothManager)getSystemService(BLUETOOTH_SERVICE);BluetoothAdapter a=bm==null?null:bm.getAdapter();if(a==null||!a.isEnabled()){status.setText("Bitte Bluetooth einschalten.");return;}Intent s=new Intent(this,H5179ScanService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(s);else startService(s);status.setText("BLE-Rohdiagnose läuft …");}
 private boolean hasPerm(){if(Build.VERSION.SDK_INT>=31)return checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)==PackageManager.PERMISSION_GRANTED;return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 private void request(){ArrayList<String>p=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){p.add(Manifest.permission.BLUETOOTH_SCAN);p.add(Manifest.permission.BLUETOOTH_CONNECT);}else p.add(Manifest.permission.ACCESS_FINE_LOCATION);if(Build.VERSION.SDK_INT>=33)p.add(Manifest.permission.POST_NOTIFICATIONS);requestPermissions(p.toArray(new String[0]),REQ);}
 @Override public void onRequestPermissionsResult(int r,String[]p,int[]g){super.onRequestPermissionsResult(r,p,g);if(r==REQ&&hasPerm())start();}
 private void refresh(){SharedPreferences p=getSharedPreferences(H5179ScanService.PREFS,MODE_PRIVATE);boolean h=p.contains("temperature");sensor.setText(p.getString("sensorName","—"));temp.setText(h?String.format(Locale.GERMANY,"%.2f °C",p.getFloat("temperature",0)):"—");hum.setText(h?String.format(Locale.GERMANY,"%.2f %%",p.getFloat("humidity",0)):"—");bat.setText(h?p.getInt("battery",-1)+" %":"—");rssi.setText(h?p.getInt("rssi",0)+" dBm":"—");long ts=p.getLong("timestamp",0);updated.setText(ts>0?DateFormat.getDateTimeInstance().format(new Date(ts)):"—");String d=p.getString("diagnostics","");diag.setText(d.isEmpty()?"Noch keine Diagnose.":d);}
 private void widget(){AppWidgetManager m=AppWidgetManager.getInstance(this);ComponentName c=new ComponentName(this,ClimateWidgetProvider.class);if(Build.VERSION.SDK_INT>=26&&m.isRequestPinAppWidgetSupported())m.requestPinAppWidget(c,null,null);else Toast.makeText(this,"Startbildschirm lange drücken → Widgets → Grow H5179 Test",Toast.LENGTH_LONG).show();}
}
